#wemd .wemd-brand-sign[data-variant="brand-sign-brand-default"] {
  display: flex;
  align-items: center;
  gap: 1em;
  padding: 1.25em;
  border-top: 2px solid #3B82F6;
  margin-top: 2em;
}
#wemd .wemd-brand-sign[data-variant="brand-sign-brand-default"] .wemd-brand-logo {
